INSERT IGNORE INTO medallas (codigo, nombre, descripcion, icono, categoria, condicion, meta, idioma_id, nivel, color, orden) SELECT CONCAT('c1_', LOWER(i.codigo)), CONCAT('C1 de ', CASE i.codigo WHEN 'EN' THEN 'inglés' ELSE 'español' END), CONCAT('Terminaste el nivel C1 de ', CASE i.codigo WHEN 'EN' THEN 'inglés' ELSE 'español' END), 'fa-flag-checkered', 'ruta', 'ruta_nivel', 1, i.id, 'C1', 'rojo', CASE i.codigo WHEN 'EN' THEN 120 ELSE 121 END FROM idiomas i WHERE i.codigo IN ('EN', 'ES');
